'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search),id=params.get('project')||'callwave',embedded=params.has('embed');
const names={callwave:'CallWave',redlegal:'RedLegal',cachai:'cachaix',eflocks:'eflocks.',rbx:'RBX'};
const reports=[{title:'La visita a Los Olmos',place:'Los Olmos · Plaza del sector',category:'Alumbrado',urgency:'Prioridad de revisión',people:'Equipo territorial · Vecinos del sector',quote:'En la visita a Los Olmos vimos tres luminarias apagadas junto a la plaza. Dos vecinos dijeron que el problema lleva varios días. Hay que coordinar con alumbrado una revisión esta semana y volver a llamar para confirmar si quedó resuelto.',owner:'Equipo de alumbrado',due:'Esta semana',status:0,resolution:''},{title:'Agua frente al centro comunitario',place:'Los Olmos · Centro comunitario',category:'Agua',urgency:'Revisar hoy',people:'Equipo territorial · Responsable de agua',quote:'Frente al centro comunitario hay una fuga de agua. El equipo territorial la vio esta mañana. Necesitamos confirmar quién la revisa hoy, registrar qué se hizo y avisar al centro cuando esté resuelto.',owner:'Equipo de agua',due:'Hoy',status:0,resolution:''},{title:'Un nuevo aviso de iluminación',place:'Los Olmos · Acceso a la plaza',category:'Alumbrado',urgency:'Prioridad de revisión',people:'Equipo territorial · Vecinos del sector',quote:'En el acceso a la plaza nos volvieron a mencionar las luminarias apagadas. Puede ser el mismo problema registrado en la visita. Antes de duplicar la gestión, hay que revisar ese compromiso y confirmar el resultado.',owner:'Equipo de alumbrado',due:'Esta semana',status:0,resolution:''}];
const seeds={callwave:{selected:0,cases:reports},redlegal:{stage:0,answers:[],files:[],messages:[],checks:[]},cachai:{side:'white',saved:[],interests:[],hidden:[],intent:'Conversar'},eflocks:{member:false,interests:[],bookings:[],unlocked:false},rbx:{episode:0,shot:0}};
if(!names[id])location.replace('index.html');
let data;try{data=JSON.parse(localStorage.getItem('wmp-immersive-v1-'+id)||'null')}catch{}data=validData(data)?data:structuredClone(seeds[id]);
let screen='home',busy=false,filter='Todos',selectedDrop='sesion',selectedProfile='Aurora',selectedFilm='sombras',config={chatUrl:'',dataUrl:'',token:''},syncTimer,legalReply='',editing=false,sourceOpen=false,isPlaying=false,pendingDrop=false,exportURL='',trail=[];
function validData(v){if(!v||typeof v!=='object')return false;for(const[k,x]of Object.entries(seeds[id]))if(Array.isArray(x)?!Array.isArray(v[k]):typeof v[k]!==typeof x)return false;if(id==='callwave')return v.cases.length>0&&v.cases.every(c=>c&&['title','place','category','quote','owner','due','resolution','urgency','people'].every(k=>typeof c[k]==='string')&&Number.isInteger(c.status)&&c.status>=0&&c.status<=3)&&Number.isInteger(v.selected)&&v.selected>=0&&v.selected<v.cases.length;if(id==='redlegal')return Number.isInteger(v.stage)&&v.stage>=0&&v.stage<=5&&v.answers.every(x=>typeof x==='string')&&v.files.every(f=>f&&typeof f.name==='string'&&typeof f.url==='string'&&/^data:(application\/pdf|image\/(png|jpeg|webp));base64,/.test(f.url));if(id==='eflocks')return v.bookings.every(x=>x&&typeof x.id==='string'&&typeof x.code==='string');if(id==='cachai')return ['white','dark'].includes(v.side)&&['saved','interests','hidden'].every(k=>v[k].every(x=>typeof x==='string'));return Number.isInteger(v.episode)&&v.episode>=0&&v.episode<3&&Number.isInteger(v.shot)&&v.shot>=0&&v.shot<5;}
function persist(){try{localStorage.setItem('wmp-immersive-v1-'+id,JSON.stringify(data));status('Guardado en este navegador');if(config.dataUrl){clearTimeout(syncTimer);syncTimer=setTimeout(async()=>{try{const r=await request(config.dataUrl,{project:id,action:'save',data});status(r.ok===true?'Sincronizado con tu workflow':'Guardado local · sincronización pendiente')}catch{status('Guardado local · sincronización pendiente')}},700)}}catch{notice('No se pudo guardar. Puedes exportar una copia.')}}
function status(text){if(embedded)parent.postMessage({type:'wmp-status',text},location.origin)}
function notice(text){$('#notice').textContent=text;$('#notice').classList.add('show');setTimeout(()=>$('#notice').classList.remove('show'),4000)}
async function request(url,payload){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',...(config.token?{Authorization:'Bearer '+config.token}:{})},body:JSON.stringify(payload),signal:controller.signal});if(!r.ok)throw Error('HTTP '+r.status);return await r.json()}finally{clearTimeout(timeout)}}
function download(name,text,type='text/plain;charset=utf-8'){if(embedded){parent.postMessage({type:'wmp-export',name,text,mime:type},location.origin);return}if(exportURL)URL.revokeObjectURL(exportURL);exportURL=URL.createObjectURL(new Blob([text],{type}));const previous=$('#file-output');if(previous)previous.remove();const box=document.createElement('aside');box.id='file-output';box.className='file-output';box.innerHTML=`<div><h2>Tu archivo está preparado.</h2><p>${esc(name)}</p></div><a class="secondary" href="${exportURL}" download="${esc(name)}">Descargar archivo</a><details><summary>Ver el contenido antes de descargar</summary><pre>${esc(text)}</pre></details>`;$('main').appendChild(box);size();box.scrollIntoView({behavior:'smooth',block:'center'})}
function action(act,text,cls='primary',extra=''){return `<button class="${cls}" data-act="${act}" ${extra}>${text}</button>`}
function go(next){if(next!==screen)trail.push({screen,selectedDrop,selectedProfile,selectedFilm,shot:data.shot});screen=next;render();if(embedded)parent.postMessage({type:'wmp-scene'},location.origin);else window.scrollTo({top:0,behavior:'smooth'})}
function stepBack(){const prev=trail.pop();if(!prev){screen='home'}else{screen=prev.screen;selectedDrop=prev.selectedDrop;selectedProfile=prev.selectedProfile;selectedFilm=prev.selectedFilm;if(id==='rbx'&&Number.isInteger(prev.shot))data.shot=prev.shot}render();if(embedded)parent.postMessage({type:'wmp-scene'},location.origin);else window.scrollTo({top:0,behavior:'smooth'})}
function wrap(content,nav=''){if(exportURL){URL.revokeObjectURL(exportURL);exportURL=''}document.body.className=id+(id==='cachai'&&screen!=='home'&&data.side==='dark'?' dark':'');$('#app').innerHTML=`<header class="app-header"><button class="brand" data-act="home">${names[id]}</button><nav>${screen!=='home'?action('step-back','‹ Volver','back-control'):''}${nav}</nav></header>${content}<footer class="app-footer">${screen!=='home'?action('step-back','‹ Volver atrás','quiet'):''}<span>${id==='rbx'?'Formato propuesto · Imágenes ilustrativas':'Experiencia de prueba · Datos ficticios'}</span>${id==='rbx'?'':action('data','Mis datos','quiet')}<span>${config.chatUrl?'IA conectada':'Funciones locales'}</span></footer>`;size()}
function render(){if(screen==='data')return dataPage();({callwave:wave,redlegal:legal,cachai:cinema,eflocks:flocks,rbx:collision})[id]()}
function size(){if(embedded)requestAnimationFrame(()=>parent.postMessage({type:'wmp-height',height:Math.ceil($('#app').getBoundingClientRect().height+2)},location.origin))}
new ResizeObserver(size).observe($('#app'));
function dataPage(){wrap(`<main class="data-scene"><h1>Tus datos de prueba.</h1><p>Se guardan en este navegador. Puedes exportarlos o cargar una copia desde tu workflow de n8n.</p><div class="actions">${action('export-json','Exportar copia')}${action('load-data','Cargar del workflow','secondary')}${action('ask-reset','Restaurar ejemplo','quiet')}</div><div id="reset-confirm"></div><div class="actions">${action('resume','Volver a la experiencia','secondary')}</div></main>`)}
// PULSO: una visita de terreno se convierte en un compromiso trazable.
function waveSteps(current){return `<nav class="journey" aria-label="Recorrido PULSO">${[['listen','El reporte'],['signals','La señal'],['commitment','El compromiso'],['followup','El resultado']].map(([s,t],i)=>`<button data-act="wave-scene" data-scene="${s}" class="${s===current?'active':''}"><span class="journey-dot ${['listen','signals','commitment','followup'].indexOf(current)>i?'done':''}"></span>${t}</button>`).join('')}</nav>`}
function soundOrb(cls=''){return `<div class="sound-orb ${cls}" aria-hidden="true"><div class="orb-inner"></div><div class="sound-bars">${Array.from({length:13},(_,i)=>`<i style="--h:${25+Math.sin(i*.6)*22+35}px;--delay:${i*.09}s"></i>`).join('')}</div><span class="orb-ring"></span><span class="orb-ring two"></span></div>`}
function wave(){const c=data.cases[data.selected],related=data.cases.filter(x=>x.place.split(' · ')[0]===c.place.split(' · ')[0]&&x.category===c.category),nav=action('wave-scene','Los reportes','quiet','data-scene="listen"');if(screen==='home'){wrap(`<main class="wave-home"><div class="wave-copy"><h1>Una voz.<br><span>Algo cambia.</span></h1><p>PULSO conecta lo que se escucha en terreno con lo que el equipo se compromete a hacer.</p><div class="actions">${action('wave-start','Recorrer PULSO <span aria-hidden="true">＋</span>')}${action('new-report','Probar con mi relato','secondary')}</div><div class="plus-note"><b>El siguiente paso de CallWave</b><p>Voz y WhatsApp ya existen. Mi propuesta suma señales, compromisos y evidencia de lo que pasó después.</p></div></div><div class="wave-visual">${soundOrb()}<span class="orbit-label l1">Lo que ocurre</span><span class="orbit-label l2">Quién responde</span><span class="orbit-label l3">Qué cambió</span><div class="audio-caption"><span class="live-dot"></span> De una visita en terreno a una gestión concreta.</div></div></main>`,nav);return}
if(screen==='new-report'){wrap(`<main class="scene wave-scene"><div class="scene-title"><h1>Cuéntalo como<br>lo contarías.</h1><p>Usa un relato ficticio de terreno. Vamos a preparar una señal y un compromiso sobre él.</p></div><form id="new-report" class="report-form"><label for="report-text">Tu reporte</label><textarea id="report-text" name="quote" required maxlength="3000" placeholder="Visitamos el sector, encontramos… y acordamos…"></textarea><div class="input-pair"><label>Título<input name="title" required maxlength="100" placeholder="La visita al sector"></label><label>Lugar<input name="place" required maxlength="150" placeholder="Sector · Referencia"></label></div><button class="primary">Construir la señal ＋</button></form>${action('home','Volver','quiet')}</main>`,nav);return}
let content='';if(screen==='listen'){content=`<div class="wave-listen-grid"><div><h1>Todo empieza<br>escuchando.</h1><p>Audio de un funcionario después de una visita. El relato conserva el contexto; PULSO lo convierte en una ruta de acción.</p><div class="report-picker">${data.cases.map((x,i)=>`<button data-case="${i}" class="${i===data.selected?'active':''}"><span>${esc(x.title)}</span><small>${esc(x.category)}</small></button>`).join('')}</div></div><div class="voice-card">${soundOrb(isPlaying?'playing':'')}<blockquote>“${esc(c.quote)}”</blockquote>${action('listen',isPlaying?'Detener voz':'Escuchar el ejemplo','audio-button')}<p class="fine">Voz sintetizada del navegador · Relato ficticio</p></div></div><div class="scene-end"><span>El contexto ya está. Ahora hagamos algo con él.</span>${action('signals','Ver la señal ＋')}</div>`}
if(screen==='signals'){content=`<div class="scene-title"><h1>El relato toma<br>forma.</h1><p>Una vista que permite actuar sin reconstruir toda la conversación.</p></div><div class="signals-layout"><div class="signal-map"><div class="map-grid" aria-hidden="true"></div><span class="map-road one"></span><span class="map-road two"></span><div class="map-pin"><span></span><b>${esc(c.place.split(' · ')[0])}</b></div><div class="map-marker m1"></div><div class="map-marker m2"></div><div class="map-legend">Mapa conceptual del ejemplo</div><div class="pattern-card"><b>${related.length>1?'Una señal que se repite.':'Un punto para revisar.'}</b><p>${related.length>1?related.length+' reportes de '+esc(c.category.toLowerCase())+' en el mismo sector. Revisar si corresponden al mismo incidente evita duplicar gestiones.':'La señal queda vinculada a su sector y conserva el relato original.'}</p></div></div><div class="signal-facts"><div><span>Qué ocurre</span><h2>${esc(c.category)}</h2></div><div><span>Dónde</span><p>${esc(c.place)}</p></div><div><span>Urgencia del ejemplo</span><p>${esc(c.urgency)}</p></div><div><span>Quiénes están involucrados</span><p>${esc(c.people)}</p></div>${c.summary?`<div><span>Resumen del asistente</span><p>${esc(c.summary)}</p></div>`:''}<details><summary>Ver de dónde sale la señal</summary><blockquote>${esc(c.quote)}</blockquote><p class="fine">Fuente: relato ficticio de la visita. La clasificación local puede corregirse.</p></details></div></div><div class="scene-end"><span>Una señal útil necesita un responsable.</span>${action('commitment','Preparar compromiso ＋')}</div>`}
if(screen==='commitment'){content=`<div class="commit-grid"><div><h1>Que no quede<br>en “lo vemos”.</h1><p>El equipo acuerda una acción, un responsable y cuándo volver a revisar. La señal permanece junto al compromiso.</p><div class="mini-signal"><span>${esc(c.category)}</span><b>${esc(c.place)}</b><p>${esc(c.quote)}</p></div></div><form id="commitment" class="commit-card"><h2>Un compromiso claro.</h2><label for="owner">Quién se hace cargo</label><input id="owner" name="owner" value="${esc(c.owner)}" required maxlength="150"><label for="due">Cuándo se revisa</label><input id="due" name="due" value="${esc(c.due)}" required maxlength="150"><label for="category">Tema de la gestión</label><input id="category" name="category" value="${esc(c.category)}" required maxlength="100"><div class="actions"><button class="primary">Guardar y seguir ＋</button></div><p class="fine">El ejemplo no envía avisos a un equipo real.</p></form></div>`}
if(screen==='followup'){content=`<div class="scene-title"><h1>${c.status===3?'Ahora sabemos<br>qué cambió.':'Volver a mirar<br>también importa.'}</h1><p>${c.status===3?'La resolución vuelve al contexto original. El equipo ve el resultado y puede preparar una respuesta.':'Un reporte recibido no es un resultado. Registra lo ocurrido después del compromiso.'}</p></div><div class="result-grid"><div class="before-after"><div><span>Antes</span><h2>${esc(c.category)}</h2><p>${esc(c.quote)}</p></div><div class="after ${c.status===3?'complete':''}"><span>${c.status===3?'Después':'Pendiente de comprobar'}</span><h2>${c.status===3?'Compromiso resuelto.':'Una respuesta por registrar.'}</h2><p>${c.status===3?esc(c.resolution):'Responsable: '+esc(c.owner)+' · Revisión: '+esc(c.due)}</p></div></div>${c.status===3?`<div class="reply-card"><span class="reply-icon" aria-hidden="true">✓</span><h2>El seguimiento tiene una respuesta.</h2><p>“Sobre el reporte de ${esc(c.place)}: ${esc(c.resolution)} Gracias por ayudarnos a identificarlo.”</p><p class="fine">Borrador para revisar · No se ha enviado ningún mensaje.</p><div class="actions">${action('wave-export','Exportar gestión','secondary')}${action('reopen','Volver a revisar','quiet')}</div></div>`:`<form id="resolution-form" class="commit-card"><h2>¿Qué se hizo?</h2><label for="resolution">Resultado de la revisión</label><textarea id="resolution" name="resolution" required maxlength="2000" placeholder="Qué se revisó, qué acción se tomó y qué se comprobó…"></textarea><button class="primary">Registrar resultado ＋</button></form>`}</div><div class="scene-end"><span>${data.cases.filter(x=>x.status===3).length} de ${data.cases.length} reportes del ejemplo con resultado registrado.</span>${action('wave-scene','Explorar otro reporte','secondary','data-scene="listen"')}</div>`}
wrap(`<main class="scene wave-scene">${waveSteps(screen)}${content}</main>`,nav)}
// Expediente Cero: acompañar y hacer visibles los antecedentes que faltan.
const legalQs=[{title:'¿Qué te llegó?',hint:'Puedes elegir una opción o contarlo con tus palabras.',chips:['Me llegó una citación','Recibí una denuncia','Estoy siendo investigado','Necesito ordenar mis antecedentes']},{title:'¿Qué ocurrió?',hint:'Cuéntame el contexto y qué es lo que más te preocupa. No hace falta contarlo perfecto.'},{title:'¿Cuándo ocurrió?',hint:'Una fecha aproximada también ayuda. Luego podrás corregirla.'},{title:'¿Hay una fecha o plazo escrito?',hint:'Cópialo tal como aparece. Lo dejamos anotado para que lo revise tu abogado.',chips:['No encuentro un plazo','Todavía no tengo el documento']},{title:'¿Qué quieres preguntarle a tu abogado?',hint:'Podemos reunir tus dudas y preparar juntos la consulta.',chips:['Qué debo llevar a la consulta','Qué significa lo que recibí','Qué información me falta']}];
function legalOrb(){return `<div class="companion-art" aria-hidden="true"><span></span><i></i><b></b></div>`}
function legalText(){return ['REDLEGAL · EXPEDIENTE CERO','Resumen preparado con los antecedentes aportados. Requiere revisión del profesional.','',...legalQs.flatMap((q,i)=>[q.title,data.answers[i]||'Por completar','']), 'Documentos: '+(data.files.map(f=>f.name).join(', ')||'Por reunir')].join('\n')}
function gapItems(){return [{title:'El documento que recibiste',done:data.files.length>0,text:'Adjunta una copia legible para que el profesional la revise.'},{title:'Fecha de lo ocurrido',done:!!data.answers[2],text:data.answers[2]||'Anota una fecha aproximada.'},{title:'Plazo indicado',done:!!data.answers[3]&&!/no encuentro|todavía|no tengo/i.test(data.answers[3]),text:data.answers[3]||'Copia el plazo si aparece en el documento.'},{title:'Preguntas para la consulta',done:!!data.answers[4],text:data.answers[4]||'Reúne las dudas que quieres resolver.'}]}
function legal(){const nav=action('legal-summary','Mi carpeta','quiet')+action('legal-professional','Vista del profesional','quiet');if(screen==='home'){wrap(`<main class="legal-home"><div class="legal-welcome"><h1>Vamos a<br>encontrar<br><em>el siguiente paso.</em></h1><p>Cuando te llega una denuncia, una citación o una investigación, ordenar lo que tienes puede darte un poco de claridad.</p><div class="actions">${action('legal-start',data.stage?'Continuar mi preparación':'Me llegó esto. Empecemos ＋')}</div><div class="plus-note"><b>Expediente Cero</b><p>Tu relato se convierte en un mapa del caso, una lista de vacíos y una carpeta preparada para el profesional.</p></div></div><div class="companion-cover">${legalOrb()}<p>Una pregunta a la vez.<br>Sin tener que saber por dónde empezar.</p></div></main>`,nav);return}
if(screen==='guided'&&data.stage<5){const q=legalQs[data.stage];wrap(`<main class="legal-session"><div class="companion-column">${legalOrb()}<span>Estoy aquí para ayudarte a ordenar.</span><div class="session-progress" aria-label="Progreso de preparación">${legalQs.map((_,i)=>`<i class="${i<data.stage?'done':i===data.stage?'current':''}"></i>`).join('')}</div><button class="quiet" data-act="legal-summary">Ver cómo crece mi carpeta</button></div><div class="question-scene"><div class="question-top">${data.stage?action('legal-back','Volver un paso','quiet'):''}<span>Tu preparación queda guardada.</span></div>${legalReply?`<p class="companion-reply">${esc(legalReply)}</p>`:''}<h1>${q.title}</h1><p>${q.hint}</p>${q.chips?`<div class="suggestions">${q.chips.map(t=>`<button data-answer="${esc(t)}">${t}</button>`).join('')}</div>`:''}<form id="legal-answer"><label class="sr-only" for="answer">Tu respuesta</label><textarea id="answer" name="answer" required maxlength="4000" placeholder="Te leo…" ${busy?'disabled':''}></textarea><div class="composer-end"><span>${config.chatUrl?'Asistente conectado':'Guía local · Ejemplo funcional'}</span><button class="primary" ${busy?'disabled':''}>${busy?'Preparando…':'Continuar ＋'}</button></div></form><p class="legal-boundary">El profesional revisará el significado jurídico y los próximos pasos.</p></div></main>`,nav);return}
if(screen==='legal-edit'){wrap(`<main class="legal-folder"><div class="folder-title"><h1>Tu relato puede<br>cambiar.</h1><p>Corrige lo que necesites. Tu mapa y el resumen se actualizarán juntos.</p></div><form id="legal-edit" class="edit-stack">${legalQs.map((q,i)=>`<label>${q.title}<textarea name="a${i}" maxlength="4000">${esc(data.answers[i]||'')}</textarea></label>`).join('')}<button class="primary">Actualizar carpeta ＋</button></form></main>`,nav);return}
const professional=screen==='professional';const gaps=gapItems();wrap(`<main class="legal-folder"><div class="folder-title"><div><h1>${professional?'El caso, listo<br>para revisar.':'Lo que ya<br>pudimos ordenar.'}</h1><p>${professional?'Vista de preparación para el abogado. Antecedentes declarados por la persona; no constituyen una evaluación jurídica.':'Tu relato, tus fechas y tus dudas tienen un lugar. Aquí puedes revisar lo que falta y preparar la consulta.'}</p></div><div class="folder-seal">${data.answers.filter(Boolean).length}<span>antecedentes<br>ordenados</span></div></div><div class="folder-tabs">${action('legal-summary','Mi preparación',professional?'quiet':'selected')}${action('legal-professional','Vista del profesional',professional?'selected':'quiet')}${action('legal-edit','Corregir relato','quiet')}</div><div class="case-layout"><section class="case-map"><h2>El mapa de tu caso.</h2><div class="case-line">${[['Lo recibido',data.answers[0]],['Los hechos',data.answers[1]],['La fecha',data.answers[2]],['El plazo indicado',data.answers[3]],['Tus preguntas',data.answers[4]]].map(([k,v],i)=>`<div class="case-node ${v?'filled':''}"><span class="node-dot"></span><small>${k}</small><p>${esc(v||'Por completar')}</p></div>`).join('')}</div>${professional?`<div class="professional-note"><b>Para la revisión del profesional</b><p>Validar fechas, contexto, documentos y plazos. La carpeta conserva las palabras de la persona y permite reconocer lo que todavía necesita corroborarse.</p></div>`:''}</section><aside class="gaps-panel"><h2>Lo que falta<br>también se ve.</h2>${gaps.map(g=>`<div class="gap-item"><span class="gap-icon ${g.done?'done':''}">${g.done?'✓':'＋'}</span><div><b>${g.title}</b><p>${esc(g.text)}</p></div></div>`).join('')}<label class="upload"><input id="legal-file" type="file" accept="application/pdf,image/png,image/jpeg,image/webp"><span>＋ Añadir documento</span><small>PDF o imagen · Hasta 1,5 MB</small></label><p class="fine">Se conserva el archivo; no se interpreta sin OCR y revisión.</p>${data.files.map((f,i)=>`<div class="document-item"><a href="${esc(f.url)}" download="${esc(f.name)}">${esc(f.name)}</a><button data-remove-file="${i}" aria-label="Quitar ${esc(f.name)}">×</button></div>`).join('')}</aside></div><section class="preparation"><h2>Tu próxima conversación,<br>mejor preparada.</h2><div class="prep-checks">${['Llevar el documento completo','Confirmar las fechas con el profesional','Anotar las dudas pendientes'].map((t,i)=>`<label><input type="checkbox" data-check="${i}" ${data.checks.includes(i)?'checked':''}><span>${t}</span></label>`).join('')}</div><div class="actions">${action('legal-export','Descargar mi resumen')}${action('legal-start',data.stage<5?'Completar preparación':'Revisar mis respuestas','secondary')}</div></section></main>`,nav)}
async function legalAnswer(text){if(!text||busy)return;busy=true;data.answers[data.stage]=text;data.messages.push({mine:true,text});const step=data.stage;legalReply='';if(config.chatUrl){render();try{const r=await request(config.chatUrl,{project:id,message:text,history:data.messages,context:{stage:step,answers:data.answers}});if(typeof r.reply==='string'){legalReply=r.reply;data.messages.push({mine:false,text:r.reply})}}catch{notice('La IA no respondió. Tu preparación sigue funcionando.')}}data.stage=Math.min(5,step+1);busy=false;persist();go(data.stage===5?'summary':'guided')}
// CACHAIX: dos ambientes, intención privada y reciprocidad.
const people=[{name:'Aurora',age:30,image:'assets/aurora.webp',tag:'Actriz · Cast',bio:'La conversación me interesa más que una presentación perfecta. Me gusta descubrir qué hay detrás de una mirada.',interests:['Cine','Conversación','Música'],mutual:true,film:'sombras'},{name:'Vega',age:32,image:'assets/vega.webp',tag:'Creativa · Cast',bio:'Prefiero una curiosidad honesta. El cine, una buena historia y el humor seco suelen ser un buen comienzo.',interests:['Cine','Arte','Humor'],mutual:false,film:'encuentro'}];
const films=[{id:'sombras',title:'Entre sombras',cast:'Aurora',side:'dark',image:'assets/cinema.webp',desc:'Un recorrido editorial entre el personaje y la persona que lo interpreta. Concepto de producción del catálogo Dark.'},{id:'encuentro',title:'Un encuentro',cast:'Vega',side:'white',image:'assets/listening-room.webp',desc:'Un ambiente sugerente construido desde una conversación y una mirada. Concepto de producción del catálogo White.'}];
function cachaiNav(){return action('cachai-discover','Descubrir','quiet')+action('cachai-matches','Mutual','quiet')+action('cachai-catalog','Producciones','quiet')+action('cachai-side','Cambiar de lado','quiet')}
function cinema(){if(screen==='home'){wrap(`<main class="cachai-entry"><div class="entry-heading"><h1>¿De qué<br><em>lado estás?</em></h1><p>White y Dark. Dos maneras de entrar.<br>Ambas para mayores de 18.</p></div><div class="split-world"><button class="choose-side white-side" data-side="white"><img src="assets/aurora.webp" alt="Aurora, personaje ficticio adulto"><span class="side-name">White</span><span class="side-copy">Sensual. Sugerente.<br>La curiosidad empieza aquí.</span><span class="side-enter">Elegir White ＋</span></button><button class="choose-side dark-side" data-side="dark"><img src="assets/vega.webp" alt="Vega, personaje ficticio adulto"><span class="side-name">Dark</span><span class="side-copy">Más intensidad.<br>Más cerca de la historia.</span><span class="side-enter">Elegir Dark ＋</span></button><div class="split-mark" aria-hidden="true">c.</div></div><div class="age-entry"><label><input type="checkbox" id="age"> Tengo 18 años o más.</label><p id="age-message" role="status"></p><p class="fine">Personajes e intereses ficticios. No crea una cuenta ni contacta a personas reales.</p></div><div class="cachai-plus"><h2>El interés no se expone.<br><em>Se encuentra.</em></h2><p>La división de ambientes es el punto de partida. Mi aporte es Mutual: expresar una intención en privado y revelarla solo cuando es recíproca.</p></div></main>`);return}
if(screen==='profile'){const p=people.find(x=>x.name===selectedProfile),interested=data.interests.includes(p.name),saved=data.saved.includes(p.name),mutual=interested&&p.mutual;wrap(`<main class="profile-scene"><button class="back-link" data-act="cachai-discover">Volver a descubrir</button><div class="profile-layout"><div class="profile-portrait"><img src="${p.image}" alt="${p.name}, personaje ficticio adulto"><span>${p.tag}</span></div><div class="profile-copy"><span class="profile-meta">${p.age} años · Personaje ficticio</span><h1>${p.name}<span>.</span></h1><p class="profile-bio">${p.bio}</p><div class="interest-tags">${p.interests.map(t=>`<span>${t}</span>`).join('')}</div><label class="intent-label" for="intent">Tu intención, solo para ti</label><select id="intent"><option ${data.intent==='Conversar'?'selected':''}>Conversar</option><option ${data.intent==='Conectar por intereses'?'selected':''}>Conectar por intereses</option><option ${data.intent==='Conocer su trabajo'?'selected':''}>Conocer su trabajo</option></select><div class="actions">${action('interest',interested?'Retirar interés':'Me interesa ＋')}${action('save-profile',saved?'Guardado ✓':'Guardar perfil','secondary')}</div><div class="mutual-state ${mutual?'reciprocal':''}"><span class="mutual-symbol" aria-hidden="true">${mutual?'∞':'◌'}</span><div><h2>${mutual?'La curiosidad era mutua.':interested?'Tu interés sigue siendo privado.':'Tú decides qué revelar.'}</h2><p>${mutual?'Esta coincidencia ilustra cómo se revelaría el interés cuando ambos lo comparten. Nadie real ha recibido un aviso.':interested?'El otro lado solo lo sabría si también comparte interés. Puedes retirarlo cuando quieras.':'Un interés unilateral permanece privado. La coincidencia es lo que abre la puerta.'}</p></div></div>${data.side==='dark'?`<div class="cast-story"><span>Del personaje a su historia</span><h2>${p.name} también<br>tiene algo que contar.</h2><p>Conecta el cast con su producción. El interés y el catálogo conviven sin que la persona pierda el control.</p><button class="text-button" data-film="${p.film}">Explorar su producción ＋</button></div>`:''}<button class="quiet" data-act="hide-profile">Ocultar este perfil</button></div></div></main>`,cachaiNav());return}
if(screen==='film'){const f=films.find(x=>x.id===selectedFilm);wrap(`<main class="film-scene"><button class="back-link" data-act="cachai-catalog">Volver a producciones</button><div class="film-cover"><img src="${f.image}" alt="Ambiente ilustrativo de ${f.title}"><div><span>Producción conceptual · 18+</span><h1>${f.title}</h1></div></div><div class="film-copy"><div><p>${f.desc}</p><p class="fine">Concepto visual. No incluye reproducción de una película real.</p></div><div><h2>La historia sigue<br>en su protagonista.</h2><button class="text-button" data-profile="${f.cast}">Conocer a ${f.cast} ＋</button></div></div></main>`,cachaiNav());return}
const matches=screen==='matches',saved=filter==='Guardados',catalog=screen==='catalog',list=people.filter(p=>!data.hidden.includes(p.name)&&(!matches||data.interests.includes(p.name)&&p.mutual)&&(!saved||data.saved.includes(p.name)));
wrap(`<main class="cachai-discovery"><div class="discovery-title"><h1>${catalog?'Detrás de<br>cada historia.':matches?'Cuando la curiosidad<br>va en ambos sentidos.':data.side==='white'?'Una mirada.<br>Un comienzo.':'Hay más detrás<br>de una mirada.'}</h1><div><p>${catalog?'El catálogo conecta con su cast. Explora una producción y descubre quién está detrás.':matches?'Mutual revela únicamente los intereses recíprocos. Este ejemplo representa una coincidencia local.':data.side==='white'?'Descubre sin complicarlo. Guarda un perfil, elige tu intención y deja que la reciprocidad haga el resto.':'Un recorrido más pausado. Descubre perfiles de cast y pasa de la producción a la persona, a tu ritmo.'}</p><span class="world-pill">${data.side==='white'?'White · Sensual y sugerente':'Dark · Mayor intensidad'}</span></div></div>${catalog?`<div class="film-grid">${films.filter(f=>data.side==='dark'||f.side==='white').map(f=>`<button class="production-card" data-film="${f.id}"><img src="${f.image}" alt="Ambiente conceptual de ${f.title}"><div><small>Cast · ${f.cast}</small><h2>${f.title}</h2><span>Explorar ＋</span></div></button>`).join('')}</div>`:`<div class="discovery-tools"><div>${['Todos','Guardados'].map(x=>`<button data-filter="${x}" class="${filter===x?'active':''}">${x}</button>`).join('')}</div>${action('restore-profiles','Restaurar perfiles ocultos','quiet')}</div><div class="people-grid">${list.length?list.map(p=>`<button class="person-card" data-profile="${p.name}"><img src="${p.image}" alt="${p.name}, personaje ficticio de ${p.age} años"><div><span>${p.tag}</span><h2>${p.name}<small>${p.age}</small></h2><p>${p.interests.join(' · ')}</p><span class="person-open">Conocer ＋</span></div>${data.interests.includes(p.name)&&p.mutual?'<span class="match-badge">Mutual ∞</span>':''}</button>`).join(''):`<div class="empty-state"><h2>${matches?'Todavía no hay coincidencias.':'Tu selección está vacía.'}</h2><p>Explora perfiles y decide qué despierta tu curiosidad.</p>${action('cachai-discover','Volver a descubrir','secondary')}</div>`}</div>`}<section class="privacy-strip"><span aria-hidden="true">∞</span><div><h2>La privacidad es parte<br>de la experiencia.</h2><p>Elige tu intención. Retira un interés. Oculta un perfil. Solo una coincidencia mutua revela algo.</p></div></section></main>`,cachaiNav())}
// Eflocks: un drop tangible, acceso inmediato y una próxima apertura.
const drops=[{id:'sesion',title:'Dentro de la sesión',kind:'Música',image:'assets/listening-room.webp',date:'2026-11-07T19:00:00',place:'Santiago · Espacio por confirmar',time:'7 noviembre · 19:00',capacity:'12 lugares en el ejemplo',desc:'Una sesión creativa desde dentro: prueba de sonido, interpretación y una conversación con quienes la hacen.',includes:['Acceso a la sesión de ejemplo','Prueba de sonido desde dentro','Conversación con el equipo creativo']},{id:'mesa',title:'La mesa de después',kind:'Encuentros',image:'assets/cinema.webp',date:'2026-11-14T20:00:00',place:'Santiago · Espacio por confirmar',time:'14 noviembre · 20:00',capacity:'8 lugares en el ejemplo',desc:'Un encuentro pequeño para compartir la historia detrás de un proyecto. Sin escenario, alrededor de la misma mesa.',includes:['Un encuentro en grupo pequeño','Conversación sobre el proceso','Información reunida en tu pase']},{id:'archivo',title:'El lado B',kind:'Contenido',image:'assets/editorial-stage.webp',date:'2026-11-01T12:00:00',place:'Acceso digital de prueba',time:'Disponible al guardar tu acceso',capacity:'Acceso de ejemplo',desc:'Notas, referencias y decisiones que no aparecen en la pieza final. Una ventana al proceso creativo.',includes:['Una nota del proceso','Referencias del ejemplo','Acceso inmediato dentro de la web']}];
function flocksNav(){return action('flocks-drops','Drops','quiet')+action('flocks-pass','Mi pase','quiet')}
function passCard(){return `<div class="membership-card"><span class="pass-top">eflocks.<i class="card-chip"></i></span><span class="pass-mark">e.</span><div class="pass-bottom"><span>MIEMBRO DE PRUEBA</span><b>${data.bookings.length?data.bookings.length+' acceso'+(data.bookings.length>1?'s':''):'Tu siguiente historia'}</b></div></div>`}
function flocks(){if(screen==='home'){wrap(`<main class="flocks-home"><div class="flocks-copy"><h1>Hay cosas<br>que solo pasan<br><em>dentro.</em></h1><p>No basta con tener una membresía. Tiene que haber algo que quieras vivir con ella.</p><div class="actions">${action('flocks-enter',data.member?'Volver a mis drops ＋':'Descubrir mi primer drop ＋')}</div><div class="plus-note"><b>Del beneficio a “ya estoy dentro”</b><p>Mi aporte suma aperturas limitadas, acceso inmediato y un pase que hace tangible lo que desbloqueas.</p></div></div><div class="flocks-visual"><img class="room-image" src="assets/listening-room.webp" alt="Espacio conceptual de una experiencia Eflocks"><div class="vinyl" aria-hidden="true"><span>e.</span></div>${passCard()}</div></main>`,flocksNav());return}
if(screen==='onboarding'){wrap(`<main class="member-onboarding"><div><h1>Tu pase.<br>A tu manera.</h1><p>Elige lo que te mueve. La selección ordena los drops que vas a descubrir.</p><form id="membership"><div class="interest-choices">${['Música','Encuentros','Contenido'].map((x,i)=>`<label><input type="checkbox" name="interest" value="${x}" ${data.interests.includes(x)?'checked':''}><span><b>${x}</b><small>${['Más cerca del escenario','Compartir el proceso','Lo que no sale al final'][i]}</small></span></label>`).join('')}</div><button class="primary">Activar mi pase de prueba ＋</button><p class="fine">No cobra, no contrata una membresía y no reserva una experiencia real.</p></form></div><div class="onboard-pass">${passCard()}</div></main>`,flocksNav());return}
if(screen==='drop'){const d=drops.find(x=>x.id===selectedDrop),booked=data.bookings.some(b=>b.id===d.id);wrap(`<main class="drop-detail"><button class="back-link" data-act="flocks-drops">Volver a los drops</button><div class="drop-detail-grid"><div class="drop-image"><img src="${d.image}" alt="Concepto de ${d.title}"><span>DROP · ${d.kind.toUpperCase()}</span></div><div class="drop-detail-copy"><h1>${d.title}<span>.</span></h1><p>${d.desc}</p><div class="drop-facts"><div><small>Cuándo</small><b>${d.time}</b></div><div><small>Dónde</small><b>${d.place}</b></div><div><small>Acceso</small><b>${d.capacity}</b></div></div><h2>Esto abre la puerta a:</h2><ul>${d.includes.map(x=>`<li>${x}</li>`).join('')}</ul>${action('claim',booked?'Abrir mi acceso ＋':data.member?'Guardar mi lugar ＋':'Activar mi pase y continuar ＋')}<p class="fine">Experiencia y cupos ilustrativos · Sin pago ni reserva real.</p></div></div></main>`,flocksNav());return}
if(screen==='ticket'){const d=drops.find(x=>x.id===selectedDrop),b=data.bookings.find(x=>x.id===d.id);if(!b){screen='drops';return flocks()}wrap(`<main class="ticket-scene"><div class="ticket-heading"><span class="ticket-check" aria-hidden="true">✓</span><h1>Ya estás<br><em>dentro.</em></h1><p>Tu acceso está en el pase. El drop dejó de ser una promesa: ya tiene lugar, información y continuidad.</p></div><div class="ticket"><img src="${d.image}" alt="${d.title}"><div class="ticket-body"><span>ACCESO DE PRUEBA</span><h2>${d.title}</h2><p>${d.time}</p><p>${d.place}</p><div class="ticket-stub"><b>${b.code}</b><span class="barcode" aria-hidden="true"></span></div></div></div><div class="ticket-next"><h2>Y la historia sigue.</h2><p>${d.id==='archivo'?'Una nota del proceso ya está disponible para leer.':'Mientras llega la fecha, puedes descubrir una nota del proceso. El próximo drop queda preparado para una nueva apertura.'}</p><div class="actions">${action('open-inside','Abrir lo que desbloqueé')}${action('calendar','Guardar en calendario','secondary')}${action('flocks-pass','Ir a mi pase','quiet')}</div></div></main>`,flocksNav());return}
if(screen==='inside'){wrap(`<main class="inside-scene"><div class="inside-image"><img src="assets/editorial-stage.webp" alt="Escenario editorial ilustrativo"><span>EL LADO B</span></div><div class="inside-copy"><h1>Antes del<br>primer acorde.</h1><p>Una sesión empieza mucho antes de tocar. Se decide el espacio, se prueba el sonido y se descubre qué necesita la canción para respirar.</p><p>Este contenido de ejemplo muestra cómo el acceso puede abrir algo en el momento: una nota del proceso, una referencia o una invitación que no aparece fuera.</p><span class="inside-label">Contenido ilustrativo desbloqueado con tu pase</span><div class="actions">${action('flocks-pass','Volver a mi pase','secondary')}${action('flocks-drops','Seguir descubriendo','quiet')}</div></div></main>`,flocksNav());return}
const pass=screen==='pass';const ordered=[...drops].sort((a,b)=>Number(data.interests.includes(b.kind))-Number(data.interests.includes(a.kind)));wrap(`<main class="drops-scene"><div class="drops-title"><div><h1>${pass?'Lo que ya<br>es parte de ti.':'Lo próximo<br>que vas a vivir.'}</h1><p>${pass?'Tu membresía se vuelve concreta en cada acceso. Todo lo que guardaste está aquí.':'Drops con una apertura, un lugar y algo que sucede después de entrar.'}</p></div>${pass?passCard():`<div class="drop-counter"><b>${data.member?'Dentro.':'Tu lugar.'}</b><span>${data.member?'Pase de prueba activo':'Disponible para descubrir'}</span></div>`}</div>${pass?`${!data.member?`<div class="empty-state"><h2>Tu pase todavía espera.</h2>${action('flocks-enter','Activar pase de prueba')}</div>`:''}<div class="saved-accesses">${data.bookings.length?data.bookings.map(b=>{const d=drops.find(x=>x.id===b.id);return d?`<div class="access-row"><img src="${d.image}" alt=""><div><small>${d.kind}</small><h2>${d.title}</h2><p>${d.time}</p></div><button class="secondary" data-ticket="${d.id}">Abrir acceso ＋</button><button class="quiet" data-cancel="${d.id}">Quitar</button></div>`:''}).join(''):`<p class="empty-copy">Tu primer acceso empieza con un drop.</p>${action('flocks-drops','Descubrir drops ＋')}`}</div><div id="cancel-confirm"></div>${data.unlocked?`<button class="inside-preview" data-act="open-inside"><span>Desbloqueado</span><h2>El lado B</h2><p>Leer la nota del proceso ＋</p></button>`:''}`:`<div class="drop-filters">${['Todos','Música','Encuentros','Contenido'].map(x=>`<button data-filter="${x}" class="${filter===x?'active':''}">${x}</button>`).join('')}</div><div class="drop-grid">${ordered.filter(d=>filter==='Todos'||d.kind===filter).map(d=>`<button class="drop-card" data-drop="${d.id}"><div><img src="${d.image}" alt="Ambiente de ${d.title}"><span>${data.bookings.some(b=>b.id===d.id)?'EN TU PASE':'DROP · '+d.kind.toUpperCase()}</span></div><h2>${d.title}</h2><p>${d.time}</p><span class="drop-open">Descubrir ＋</span></button>`).join('')}</div>`}<section class="next-drop"><div class="lock-orbit" aria-hidden="true">＋</div><div><span>La próxima apertura</span><h2>Algo más está<br>por llegar.</h2><p>El siguiente drop se revela cuando la comunidad tenga una nueva experiencia. En esta prueba permanece cerrado.</p></div><span class="locked-pill">Próximamente</span></section></main>`,flocksNav())}
function calendar(){const d=drops.find(x=>x.id===selectedDrop),stamp=d.date.replace(/[-:]/g,'');download('eflocks-'+d.id+'.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Eflocks//Demo//ES','BEGIN:VEVENT','UID:eflocks-demo-'+d.id,'DTSTAMP:20261007T120000Z','DTSTART;TZID=America/Santiago:'+stamp,'SUMMARY:'+d.title+' - ejemplo Eflocks','LOCATION:'+d.place,'DESCRIPTION:Acceso ilustrativo. No corresponde a un evento real confirmado.','END:VEVENT','END:VCALENDAR'].join('\r\n'),'text/calendar;charset=utf-8')}
// COLLISION: formato audiovisual, no aplicación de votos ni concurso real.
const episodes=[{title:'El hit cambia de piel',pair:'Una banda de rock.\nUn artista urbano.',hook:'Su tema más conocido. Como nunca lo habían tocado.',challenge:'Elegir un estribillo de la banda y reinventarlo juntos como una versión de 60 segundos. Debe seguir siendo reconocible, aunque cambie de estilo.',rule:'Cambiar el ritmo y tocarlo sin guitarras.',payoff:'Escuchamos el estribillo original y luego la nueva versión. Una colaboración con un resultado que ambos pueden compartir.'},{title:'De una frase a una canción',pair:'Un rapero.\nUna banda.',hook:'Una frase del público se convierte en su próximo estribillo.',challenge:'Tomar una frase elegida entre los comentarios y crear desde cero una pieza de 60 segundos: la banda construye la música y el rapero la letra.',rule:'La frase debe aparecer tal cual y la música debe pasar de calma a energía.',payoff:'Los seguidores reconocen su frase dentro de una pieza nueva. El episodio siguiente puede empezar donde terminó este.'},{title:'El escenario es el instrumento',pair:'Dos artistas.\nSu equipo musical.',hook:'Antes de tocar, tienen que encontrar de dónde sale el sonido.',challenge:'Crear una pieza de 60 segundos usando tres sonidos encontrados en el recinto: grabarlos, convertirlos en un ritmo y cantar o tocar sobre él.',rule:'La base solo puede usar esos tres sonidos; no vale una pista preparada.',payoff:'Vemos de dónde sale cada sonido y después escuchamos cómo se convierte en música.'}];
const shots=[{title:'Primero, los invitados.',time:'Los invitados',text:'Vemos a quiénes juntamos y escuchamos unos segundos de lo que hace cada uno. Así entendemos sus estilos antes del reto.',quote:'“¿Cómo harías esto a tu manera?”'},{title:'Un reto que se entiende.',time:'El reto',text:'Los invitados descubren qué deben crear y la única regla que tienen que respetar. Disponen de 45–60 minutos para preparar una pieza de 60 segundos.',quote:'“Vamos a probar algo que ninguno haría solo.”'},{title:'Probamos. Cambiamos. Tocamos.',time:'Las pruebas',text:'Vemos cómo proponen ideas, prueban una primera versión y la ajustan juntos. El episodio conserva los errores divertidos y el momento en que la idea empieza a funcionar.',quote:'“Espera. Tócalo así otra vez.”'},{title:'Ahora sí: su nueva versión.',time:'La pieza final',text:'Los invitados interpretan los 60 segundos completos. Antes mostramos el punto de partida para que el público escuche qué cambió.',quote:'“Así empezó. Así quedó.”'},{title:'El siguiente capítulo empieza aquí.',time:'El próximo reto',text:'Los invitados eligen qué dejar al próximo capítulo: el reto o la restricción. Si proponen la restricción, el público comenta qué reto haría con ella. Si proponen el reto, los comentarios sugieren la restricción. El equipo selecciona una combinación que pueda grabarse.',quote:'“Nosotros dejamos una regla. ¿Qué harías tú con ella?”'}];
function collision(){const ep=episodes[data.episode],nav=action('rbx-concept','El formato','quiet')+action('rbx-pilot','El piloto','quiet');if(screen==='pilot'){const s=shots[data.shot];wrap(`<main class="pilot-scene"><div class="pilot-top"><button class="back-link" data-act="rbx-concept">Volver al formato</button><span>COLLISION · Así sería el episodio</span></div><div class="pilot-progress">${shots.map((x,i)=>`<button data-shot="${i}" class="${i===data.shot?'active':i<data.shot?'done':''}" aria-label="${x.title}"><i></i><span>${x.time}</span></button>`).join('')}</div><div class="pilot-frame"><img src="assets/${data.shot===2?'editorial-stage':'rbx-show'}.webp" alt="Concepto visual del episodio"><div class="frame-mark">${data.shot+1} / 5 · ${s.time}</div><div class="pilot-story"><h1>${s.title}</h1><p>${s.text}</p><div class="episode-detail">${data.shot===0?ep.pair.split('\n').map(x=>`<span>${esc(x)}</span>`).join(''):data.shot===1?`<b>${esc(ep.challenge)}</b><span>Regla: ${esc(ep.rule)}</span>`:data.shot===3?`<span>${esc(ep.payoff)}</span>`:''}</div><blockquote>${s.quote}</blockquote></div><div class="pilot-bottom"><span>${ep.title} · Participantes ilustrativos</span>${action(data.shot<4?'rbx-next-shot':'rbx-concept',data.shot<4?'Continuar el episodio ＋':'Volver al formato ＋')}</div></div><div class="pilot-context"><p>${data.shot===1?'<b>El reto de este piloto:</b> '+ep.challenge+'<br><b>La restricción:</b> '+ep.rule:'Estás recorriendo la propuesta de un episodio de YouTube. Las imágenes muestran el ambiente; la grabación se haría con los invitados y el equipo de producción.'}</p>${action('treatment','Descargar propuesta','quiet')}</div></main>`,nav);return}
wrap(`<main class="collision-home"><section class="collision-hero"><img src="assets/rbx-show.webp" alt="Concepto visual de artistas adultos colaborando en un reto"><div class="collision-brand"><h1>COLL<span class="collision-spark"><svg class="geometric-spark" viewBox="0 0 100 100" fill="none" aria-hidden="true"><path d="M50 4v92M4 50h92M17.5 17.5l65 65M17.5 82.5l65-65" stroke="currentColor" stroke-width="8"/></svg></span><br>ISION.</h1><p>Dos artistas que no esperabas juntos.<br>Un reto compartido. Una pieza que no existía.</p><div class="actions">${action('rbx-pilot','Ver cómo sería un episodio ＋')}</div></div><span class="hero-stamp">RBX<br>ORIGINAL<br>PROPUESTO</span><div class="show-tape"><span>45–60 MINUTOS PARA CREAR</span><span>60 SEGUNDOS PARA MOSTRAR</span><span>DOS MUNDOS · UNA PIEZA</span></div></section><section class="collision-explain"><h2>El encuentro<br>es el formato.</h2><div><p>RBX ya tiene escenario y comunidad. Mi aporte es una serie propia: cruzar artistas inesperados, revelar una restricción y convertir lo que pasa entre ellos en una historia para YouTube.</p><p>La pieza final es el cierre. Los intentos, las diferencias y los hallazgos son lo que hace que quieras llegar a ella.</p></div></section><section class="challenge-section"><div class="challenge-top"><h2>Una regla cambia<br>todo.</h2><p>Explora tres posibles colisiones.</p></div><div class="episode-picks">${episodes.map((x,i)=>`<button data-episode="${i}" class="${i===data.episode?'active':''}">${x.title}</button>`).join('')}</div><div class="challenge-stage"><div class="pair-card"><span>LOS INVITADOS</span><h3>${ep.pair.split('\n').join('<br><span>×</span><br>')}</h3></div><div class="challenge-copy"><h3>${ep.hook}</h3><p>${ep.challenge}</p><div class="restriction"><span>La restricción</span><b>${ep.rule}</b></div><p class="payoff">${ep.payoff}</p>${action('rbx-pilot','Ver este episodio paso a paso ＋')}</div></div></section><section class="show-cycle"><h2>No termina<br>cuando termina.</h2><div class="show-cycle-grid"><div><span class="cycle-symbol">◌</span><h3>Antes</h3><p>Se selecciona un reto y una restricción entre la propuesta de los invitados anteriores y los comentarios del público.</p></div><div><span class="cycle-symbol"><svg class="geometric-spark" viewBox="0 0 100 100" fill="none" aria-hidden="true"><path d="M50 4v92M4 50h92M17.5 17.5l65 65M17.5 82.5l65-65" stroke="currentColor" stroke-width="8"/></svg></span><h3>Durante</h3><p>Dos lenguajes chocan. Las restricciones generan decisiones, tensión y humor propios.</p></div><div><span class="cycle-symbol">↻</span><h3>Después</h3><p>Los invitados dejan el reto o la restricción del siguiente capítulo. El público propone la otra parte en comentarios.</p></div></div></section><section class="production-block"><h2>Un formato que también<br>puede sostenerse.</h2><div><details><summary>Qué produce una grabación</summary><p>Un episodio principal, la pieza final de 60 segundos, cortes verticales y una miniatura. El montaje se adapta a lo que ocurra con los invitados.</p></details><details><summary>Cómo puede generar ingresos</summary><p>Patrocinio del formato o de un reto, colaboraciones con marcas y monetización del canal cuando cumpla sus requisitos. Se propone un piloto remunerado antes de comprometer una serie.</p></details><details><summary>Qué aportaría yo</summary><p>Desarrollo del formato, dirección creativa, pauta e identidad de la serie. Coordinar la narrativa y los recursos con el equipo de RBX; la grabación la realiza su equipo de producción o el equipo que se designe.</p></details><div class="actions">${action('treatment','Descargar la propuesta','secondary')}${action('rbx-pilot','Ver la pauta visual','quiet')}</div></div></section></main>`,nav)}
function treatment(){const ep=episodes[data.episode];return ['RBX · COLLISION','Propuesta de formato de YouTube','Dos invitados inesperados. Una restricción. 45–60 minutos para crear una pieza de 60 segundos.','',ep.title,ep.pair,ep.hook,ep.challenge,'Restricción: '+ep.rule,'',...shots.flatMap(s=>[s.time,s.title,s.text,s.quote,'']),'Continuidad: los invitados dejan el reto o la restricción. El público completa la otra parte en comentarios y el equipo selecciona una combinación viable. Sin ganador: todos colaboran en una pieza común.','Ingresos propuestos: patrocinio de formato/retos y monetización del canal cuando corresponda. Piloto remunerado con alcance acordado. Mi rol: desarrollo del formato y dirección creativa. La grabación corresponde al equipo de producción que se designe.','Participantes e imágenes ilustrativos.'].join('\n')}
// Rutas y acciones inline: ninguna ventana emergente interrumpe el recorrido.
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.act;
if(a==='step-back'){stepBack();return}if(a==='home'){go('home');return}if(a==='data'){go('data');return}if(a==='resume'){go('home');return}if(a==='export-json'){download(names[id]+'-datos.json',JSON.stringify(data,null,2),'application/json');return}if(a==='ask-reset'){$('#reset-confirm').innerHTML='<p>Se reemplazan únicamente los cambios de esta prueba.</p>'+action('reset','Sí, restaurar el ejemplo','secondary');return}if(a==='reset'){data=structuredClone(seeds[id]);persist();go('home');return}if(a==='load-data'){if(!config.dataUrl){notice('Configura el webhook de datos desde Conexiones.');return}b.disabled=true;try{const r=await request(config.dataUrl,{project:id,action:'load'});if(!validData(r.data))throw Error('Formato incorrecto');data=r.data;persist();go('home');notice('Datos cargados desde tu workflow')}catch{notice('No se pudieron cargar datos válidos. Tu copia local se conserva.');b.disabled=false}return}
if(id==='callwave'){if(a==='wave-start')go('listen');if(a==='wave-scene')go(b.dataset.scene);if(a==='new-report')go('new-report');if(b.dataset.case!==undefined){data.selected=Number(b.dataset.case);persist();go('listen')}if(a==='listen'){if(!('speechSynthesis'in window)){notice('Este navegador no dispone de voz. Puedes leer el reporte.');return}if(isPlaying){speechSynthesis.cancel();isPlaying=false;render()}else{const u=new SpeechSynthesisUtterance(data.cases[data.selected].quote);u.lang='es-CL';u.rate=.96;u.onend=()=>{isPlaying=false;if(screen==='listen')render()};speechSynthesis.cancel();speechSynthesis.speak(u);isPlaying=true;render()}}if(a==='signals'){data.cases[data.selected].status=Math.max(1,data.cases[data.selected].status);persist();go('signals')}if(a==='commitment')go('commitment');if(a==='reopen'){data.cases[data.selected].status=2;persist();go('followup')}if(a==='wave-export'){const c=data.cases[data.selected];download('pulso-gestion.txt',Object.entries(c).map(([k,v])=>k+': '+v).join('\n'))}}
if(id==='redlegal'){if(a==='legal-start')go(data.stage>=5?'legal-edit':'guided');if(a==='legal-summary')go('summary');if(a==='legal-professional')go('professional');if(a==='legal-edit')go('legal-edit');if(a==='legal-back'){data.stage=Math.max(0,data.stage-1);legalReply='';persist();go('guided')}if(b.dataset.answer)await legalAnswer(b.dataset.answer);if(a==='legal-export')download('redlegal-expediente-cero.txt',legalText());if(b.dataset.removeFile!==undefined){data.files.splice(Number(b.dataset.removeFile),1);persist();render()}}
if(id==='cachai'){if(b.dataset.side){if(!$('#age').checked){$('#age-message').textContent='Confirma que tienes 18 años o más para elegir un lado.';$('#age').focus();return}data.side=b.dataset.side;persist();go('discover')}if(a==='cachai-discover'){filter='Todos';go('discover')}if(a==='cachai-matches'){filter='Todos';go('matches')}if(a==='cachai-catalog')go('catalog');if(a==='cachai-side')go('home');if(b.dataset.profile){selectedProfile=b.dataset.profile;go('profile')}if(b.dataset.film){selectedFilm=b.dataset.film;go('film')}if(b.dataset.filter){filter=b.dataset.filter;render()}if(a==='interest'){data.interests=data.interests.includes(selectedProfile)?data.interests.filter(x=>x!==selectedProfile):[...data.interests,selectedProfile];persist();render()}if(a==='save-profile'){data.saved=data.saved.includes(selectedProfile)?data.saved.filter(x=>x!==selectedProfile):[...data.saved,selectedProfile];persist();render()}if(a==='hide-profile'){data.hidden=[...new Set([...data.hidden,selectedProfile])];persist();go('discover')}if(a==='restore-profiles'){data.hidden=[];persist();render();notice('Perfiles restaurados')}}
if(id==='eflocks'){if(a==='flocks-enter'){pendingDrop=false;go(data.member?'drops':'onboarding')}if(a==='flocks-drops')go('drops');if(a==='flocks-pass')go('pass');if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.drop){selectedDrop=b.dataset.drop;go('drop')}if(b.dataset.ticket){selectedDrop=b.dataset.ticket;go('ticket')}if(a==='claim'){if(!data.member){pendingDrop=true;go('onboarding');return}if(!data.bookings.some(x=>x.id===selectedDrop))data.bookings.push({id:selectedDrop,code:'EF-'+selectedDrop.toUpperCase()+'-'+Date.now().toString(36).slice(-5).toUpperCase()});data.unlocked=true;persist();go('ticket')}if(a==='open-inside')go('inside');if(a==='calendar')calendar();if(b.dataset.cancel){$('#cancel-confirm').innerHTML='<p>¿Quitar este acceso del pase de prueba?</p>'+action('cancel-access','Quitar acceso','secondary','data-id="'+esc(b.dataset.cancel)+'"');$('#cancel-confirm').scrollIntoView({behavior:'smooth'})}if(a==='cancel-access'){data.bookings=data.bookings.filter(x=>x.id!==b.dataset.id);data.unlocked=data.bookings.length>0;persist();render()}}
if(id==='rbx'){if(a==='rbx-concept')go('home');if(a==='rbx-pilot'){data.shot=0;persist();go('pilot')}if(a==='rbx-next-shot'){trail.push({screen,selectedDrop,selectedProfile,selectedFilm,shot:data.shot});data.shot=Math.min(4,data.shot+1);persist();go('pilot')}if(b.dataset.shot!==undefined){trail.push({screen,selectedDrop,selectedProfile,selectedFilm,shot:data.shot});data.shot=Number(b.dataset.shot);persist();go('pilot')}if(b.dataset.episode!==undefined){data.episode=Number(b.dataset.episode);persist();render();$('.challenge-stage').scrollIntoView({behavior:'smooth',block:'center'})}if(a==='treatment')download('RBX-COLLISION-piloto.txt',treatment())}
});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const v=new FormData(f);if(f.id==='legal-answer')await legalAnswer(String(v.get('answer')).trim());if(f.id==='legal-edit'){data.answers=legalQs.map((_,i)=>String(v.get('a'+i)).trim());data.stage=5;persist();go('summary')}if(f.id==='new-report'){const quote=String(v.get('quote')).trim();data.cases.push({title:String(v.get('title')),place:String(v.get('place')),category:'Por revisar',urgency:'Por confirmar',people:'Por confirmar',quote,owner:'',due:'',status:1,resolution:''});data.selected=data.cases.length-1;const reportIndex=data.selected;persist();go('signals');if(config.chatUrl){try{const r=await request(config.chatUrl,{project:id,message:quote,history:[],context:{task:'Extraer problemática, urgencia, ubicación, involucrados y compromisos. Responde con resumen claro.'}});if(typeof r.reply==='string'){data.cases[reportIndex].summary=r.reply;persist();if(screen==='signals'&&data.selected===reportIndex)render();notice('El resumen del asistente está disponible con la gestión.')}}catch{notice('La IA no respondió. Puedes completar la gestión localmente.')}}}if(f.id==='commitment'){Object.assign(data.cases[data.selected],{owner:String(v.get('owner')),due:String(v.get('due')),category:String(v.get('category')),status:2});persist();go('followup')}if(f.id==='resolution-form'){data.cases[data.selected].resolution=String(v.get('resolution'));data.cases[data.selected].status=3;persist();go('followup')}if(f.id==='membership'){data.member=true;data.interests=v.getAll('interest');persist();go(pendingDrop?'drop':'drops');pendingDrop=false}});
document.addEventListener('change',e=>{if(e.target.id==='intent'){data.intent=e.target.value;persist()}if(e.target.dataset.check!==undefined){const n=Number(e.target.dataset.check);data.checks=e.target.checked?[...new Set([...data.checks,n])]:data.checks.filter(x=>x!==n);persist()}if(e.target.id==='legal-file'){const f=e.target.files[0];if(!f)return;if(f.size>1500000||!['application/pdf','image/png','image/jpeg','image/webp'].includes(f.type)){notice('Usa un PDF o imagen de hasta 1,5 MB.');return}const reader=new FileReader();reader.onload=()=>{data.files.push({name:f.name,url:reader.result});persist();render();notice('Documento añadido a tu carpeta')};reader.readAsDataURL(f)}});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent||e.data?.type!=='wmp-config')return;config=e.data.config||{};status(config.dataUrl?'Workflow disponible · Copia local activa':'Modo de prueba · Guardado local')});
render();
